import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import { stockService } from '../../services/api';
import { EXAMPLE_SYMBOLS, ERROR_MESSAGES } from '../../constants';
import '../../styles/StockSearch.css';

function StockSearch({ onStockFound }) {
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [searchTimeout, setSearchTimeout] = useState(null);

    useEffect(() => {
        return () => {
            if (searchTimeout) {
                clearTimeout(searchTimeout);
            }
        };
    }, [searchTimeout]);

    const handleSearch = async () => {
        if (!searchTerm.trim()) {
            setError('Please enter a stock symbol or company name');
            return;
        }

        try {
            setError(null);
            setIsLoading(true);
            const data = await stockService.searchStock(searchTerm);
            if (Array.isArray(data)) {
                setSearchResults(data);
            } else {
                onStockFound(data);
                setSearchTerm('');
                setSearchResults([]);
            }
        } catch (error) {
            setError(error instanceof Error ? error.message : ERROR_MESSAGES.STOCK_NOT_FOUND);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompanySearch = async (query) => {
        if (query.length < 2) {
            setSearchResults([]);
            return;
        }

        try {
            const companies = await stockService.searchCompanies(query);
            setSearchResults(companies || []);
            setError(null);
        } catch (error) {
            console.error('Company search error:', error);
            setSearchResults([]);
            setError(null); // Don't show errors to users for company search
        }
    };

    const handleInputChange = (e) => {
        const value = e.target.value;
        setSearchTerm(value);
        setError(null);

        // Clear existing timeout
        if (searchTimeout) {
            clearTimeout(searchTimeout);
        }

        // Set new timeout for company search
        if (!/^[A-Z]+$/.test(value)) {
            const timeout = setTimeout(() => handleCompanySearch(value), 300);
            setSearchTimeout(timeout);
        } else {
            setSearchResults([]);
        }
    };

    const handleCompanySelect = async (symbol) => {
        setSearchTerm(symbol);
        setSearchResults([]);
        try {
            setIsLoading(true);
            const data = await stockService.searchStock(symbol);
            onStockFound(data);
            setSearchTerm('');
        } catch (error) {
            setError(error instanceof Error ? error.message : ERROR_MESSAGES.STOCK_NOT_FOUND);
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !searchResults.length) {
            handleSearch();
        }
    };

    return (
        <div className="stock-search">
            <div className="search-container">
                <div className="search-input-wrapper">
                    <input
                        type="text"
                        value={searchTerm}
                        onChange={handleInputChange}
                        onKeyPress={handleKeyPress}
                        placeholder="Enter stock symbol or company name"
                        className={error ? 'error' : ''}
                        disabled={isLoading}
                    />
                    {searchResults.length > 0 && (
                        <div className="search-results">
                            {searchResults.map((result) => (
                                <div
                                    key={result.symbol}
                                    className="search-result-item"
                                    onClick={() => handleCompanySelect(result.symbol)}
                                >
                                    <span className="company-symbol">{result.symbol}</span>
                                    <span className="company-name">{result.name}</span>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <button
                    onClick={handleSearch}
                    disabled={isLoading || !searchTerm.trim() || searchResults.length > 0}
                    className={isLoading ? 'loading' : ''}
                >
                    {isLoading ? 'Searching...' : 'Search'}
                </button>
            </div>
            {error && <p className="error-message">{error}</p>}
            <div className="example-symbols">
                Try symbols: {EXAMPLE_SYMBOLS.join(', ')} or company names like "Apple", "Microsoft"
            </div>
        </div>
    );
}

StockSearch.propTypes = {
    onStockFound: PropTypes.func.isRequired,
};

export default StockSearch;
